#!/usr/bin/env python3
"""
Enrich auto-generated shallow markdown cells in Jupyter notebooks with
deep, concept-driven explanations that teach *what* and *why*.

Detects cells generated by the first-pass add_explanations.py script
and replaces them with rich contextual explanations based on the code
that follows.
"""

import json
import re
import sys
from pathlib import Path
from collections import Counter

WORKSPACE = Path("/Users/pavanmudigonda/code/zero-to-ai")

# ────────────────────────────────────────────────────────────────────
# DETECTION: Patterns that identify auto-generated shallow cells
# ────────────────────────────────────────────────────────────────────

AUTO_GEN_PATTERNS = [
    r"^Evaluate the (expression|arithmetic)",
    r"^Display the current value of",
    r"^This code implements the next step in",
    r"^Run this code and examine the printed output",
    r"^Set up the variables needed for the next step",
    r"^Display output to verify the results",
    r"^Execute the next step in this",
    r"^Work with Python (lists|dictionaries|dict)",
    r"^Use a (loop to process|Python comprehension)",
    r"^Use conditional logic",
    r"^Perform string manipul",
    r"^Set up variables and display",
    r"^\*\*Python (Multiplication|Division|Addition|Subtraction|Modulo|Exponentiation):\*\*",
    r"^\*\*Inspect variable",
    r"^\*\*Indexing/Slicing:\*\*",
    r"^### (Mathematical Operations|Visualize the Results|Data Manipulation|Iterative Processing|Data Transformation|File Operations|Error Handling|API Interaction|Tensor Operations|Compute Embeddings|Vector Database|Generate Predictions|Build the Model|Train the Model|Evaluate Model|Load the Data|Preprocess the Data|Configure Loss|Can not start)",
    r"^### Import Required Libraries\n\nLoad the libraries needed",
    r"^### Define the `\w+` Function\n\nDefine a function",
    r"^### Define Helper Functions\n\nDefine these utility",
    r"^### Define `\w+\(\)`\n\nA helper function",
    # Thin headings with no real explanation
    r"^### (Vector Operations|Matrix Operations|Visualizing (Vectors|Matrix|Eigenvectors))\s*$",
]


def is_auto_generated(md_source: str) -> bool:
    """Check if a markdown cell was auto-generated with shallow content."""
    text = md_source.strip()
    for pat in AUTO_GEN_PATTERNS:
        if re.search(pat, text, re.MULTILINE):
            return True
    return False


