def get_topic(nb_path: str) -> str:
    """Infer topic from notebook path."""
    p = nb_path.lower()
    for pat, topic in [
        ("token", "tokenization"), ("embedding", "embeddings"),
        ("neural", "neural networks"), ("vector.*database", "vector databases"),
        (r"\brag\b", "RAG"), ("mlops", "MLOps"), ("prompt", "prompt engineering"),
        ("finetun", "LLM fine-tuning"), ("multimodal", "multimodal AI"),
        ("agent", "AI agents"), ("evaluat|metric", "model evaluation"),
        ("debug|troubleshoot", "debugging"), ("safety|redteam", "AI safety"),
        ("streaming", "real-time streaming"), ("time.series|time_series", "time series"),
        ("reinforcement|q_learn", "reinforcement learning"),
        ("causal", "causal inference"), ("deep.learn|advanced", "deep learning"),
        ("linear.algebra", "linear algebra"), ("calculus|derivative", "calculus"),
        ("probability|statistic", "statistics"), ("gradient", "optimization"),
        ("numpy", "NumPy"), ("pandas|dataframe", "Pandas"),
        ("matplotlib", "visualization"), ("scikit|sklearn", "scikit-learn"),
        ("python|crash", "Python"), ("data.science|data_science", "data science"),
        ("local.llm|ollama", "local LLMs"), ("inference.*optim", "inference optimization"),
        ("low.code|gradio|streamlit", "low-code AI"), ("math", "mathematics"),
        ("islp", "statistical learning"), ("hardware", "AI hardware"),
        ("practical", "practical data science"),
    ]:
        if re.search(pat, p):
            return topic
    return "AI/ML"


def build_explanation(code: str, topic: str) -> str:
    """Generate a rich explanation for a code cell using concept matches."""
    explanations = []
    matched_ids = set()

    for pattern, concept_id, explanation in CONCEPTS:
        if concept_id in matched_ids:
            continue
        if re.search(pattern, code):
            explanations.append(explanation)
            matched_ids.add(concept_id)

    if explanations:
        return "\n\n".join(explanations)

    # ── Fallback: analyze code structure ──
    lines = [l.strip() for l in code.split("\n") if l.strip() and not l.strip().startswith("#")]
    comments = [l.strip().lstrip("#").strip() for l in code.split("\n")
                if l.strip().startswith("#") and len(l.strip()) > 3
                and not l.strip().startswith("#!") and not l.strip().startswith("#%%")]

    has_imports = any(re.match(r"^(import|from)\s+", l) for l in code.split("\n") if l.strip())

    if has_imports:
        imports = re.findall(r"(?:from|import)\s+(\S+)", code)
        base_libs = list(dict.fromkeys(lib.split(".")[0] for lib in imports))
        parts = ["Import the libraries needed for this section:"]
        for lib in base_libs:
            parts.append(f"- **{lib}**")
        return "\n".join(parts)

    # Use comments as explanation source
    if comments:
        if len(comments) >= 2:
            return "\n".join(f"- {c}" for c in comments[:5])
        return comments[0]

    # Simple expressions
    if len(lines) == 1 and len(lines[0]) < 50:
        expr = lines[0]
        if re.match(r"^\d+\s*[\+\-\*\/\%\*]+\s*\d+$", expr):
            ops = {"+": "addition", "-": "subtraction", "*": "multiplication",
                   "/": "division", "%": "modulo (remainder)", "**": "exponentiation"}
            for sym, name in ops.items():
                if sym in expr:
                    return (f"**Python {name.title()}:** `{expr}` — Jupyter displays "
                            "the last expression's value automatically.")
        if re.match(r"^[a-zA-Z_]\w*(\.\w+)*(\(.*\))?$", expr):
            return (f"Evaluate `{expr}` — Jupyter renders the last expression as cell output.")

    # Generic fallback using topic context
    if any(re.search(r"^print\(", l) for l in code.split("\n") if l.strip()):
        return (f"Run this cell and inspect the output to verify the {topic} "
                "operations produce the expected results.")

    return (f"The code below implements the next step in this {topic} workflow. "
            "See the inline comments for details on each operation.")


def process_notebook(nb_path: Path, topic: str) -> tuple[int, int]:
    """Replace shallow explanation cells with rich ones."""
    with open(nb_path, "r", encoding="utf-8") as f:
        nb = json.load(f)

    cells = nb.get("cells", [])
    enriched = 0
    found = 0

    for i, cell in enumerate(cells):
        if cell.get("cell_type") != "markdown":
            continue

        src = cell.get("source", "")
        if isinstance(src, list):
            src = "".join(src)

        if not is_auto_generated(src):
            continue

        found += 1

        # Find the next code cell (may be i+1 or i+2)
        code_src = ""
        for j in range(i + 1, min(i + 3, len(cells))):
            if cells[j].get("cell_type") == "code":
                code_src = cells[j].get("source", "")
                if isinstance(code_src, list):
                    code_src = "".join(code_src)
                break

        if not code_src.strip():
            continue

        new_md = build_explanation(code_src, topic)
        if new_md and new_md.strip() != src.strip():
            cell["source"] = [new_md]
            enriched += 1

    if enriched > 0:
        with open(nb_path, "w", encoding="utf-8") as f:
            json.dump(nb, f, indent=1, ensure_ascii=False)
            f.write("\n")

    return enriched, found


def main():
    nbs = sorted(WORKSPACE.rglob("*.ipynb"))
    nbs = [n for n in nbs
           if ".ipynb_checkpoints" not in str(n)
           and "site/" not in str(n)
           and ".venv/" not in str(n)
           and "node_modules/" not in str(n)]

    print(f"Scanning {len(nbs)} notebooks...\n")

    total_enriched = 0
    total_found = 0
    modified = 0

    for nb_path in nbs:
        rel = str(nb_path.relative_to(WORKSPACE))
        topic = get_topic(rel)

        try:
            enriched, found = process_notebook(nb_path, topic)
            total_found += found
            if enriched > 0:
                modified += 1
                total_enriched += enriched
                print(f"  Enriched {enriched:3d}/{found:3d}: {rel}")
        except Exception as e:
            print(f"  ERROR: {rel}: {e}")

    print(f"\n{'=' * 60}")
    print(f"Enriched {total_enriched}/{total_found} cells across {modified} notebooks")
    print(f"{'=' * 60}")


if __name__ == "__main__":
    main()
